=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (default 4).
//
// Trace: requirement req-142be1ce31 ("Create a round-robin arbiter for four
// requesters"); interface_spec.md (ports, behaviour, reset); and
// microarchitecture.md sections 1-4 (one pointer, a wrapping priority
// search against LAST, the pointer moves one past the winner, and a
// synchronous active-low reset).
//
// - The only state is ptr, $clog2(N) bits. It resets to 0.
// - grant is combinational from req and ptr. The winner is the first
//   requester with req high at or after ptr, searching upwards and wrapping
//   from N-1 to 0. The wrap compares against LAST, so it is correct for N
//   that is not a power of two.
// - On a rising edge with a grant (and reset released), ptr becomes
//   winner + 1, wrapping at N. With no request, ptr holds.
// - grant is not gated by reset. During reset ptr is forced to 0.

`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer  PW     = (N > 1) ? $clog2(N) : 1;
    localparam [31:0]   LAST32 = N - 1;
    localparam [31:0]   ONE32  = 1;
    localparam [PW-1:0] LAST   = LAST32[PW-1:0];
    localparam [PW-1:0] ONE    = ONE32[PW-1:0];
    localparam [PW-1:0] ZERO   = {PW{1'b0}};

    reg [PW-1:0] ptr;       // highest-priority requester this cycle
    reg [PW-1:0] ptr_next;  // pointer after this cycle's grant
    reg [PW-1:0] winner;    // index of the granted requester
    reg [PW-1:0] idx;       // search position
    reg          found;     // some requester was granted
    integer      k;

    // Wrapping priority search. Every output of the block gets a default
    // first, so there is no latch.
    always @* begin
        grant  = {N{1'b0}};
        winner = ptr;
        found  = 1'b0;
        idx    = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[idx]) begin
                found      = 1'b1;
                winner     = idx;
                grant[idx] = 1'b1;
            end
            if (idx == LAST) idx = ZERO;
            else             idx = idx + ONE;
        end
        if (!found)              ptr_next = ptr;
        else if (winner == LAST) ptr_next = ZERO;
        else                     ptr_next = winner + ONE;
    end

    // Pointer register: synchronous, active-low reset to 0.
    always @(posedge clk) begin
        if (!rst_n) ptr <= ZERO;
        else        ptr <= ptr_next;
    end

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 5).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) if (!f_past_valid) assume (!rst_n);

    // Distance from 'from_idx' upwards to 'to_idx', wrapping at N.
    function integer f_dist;
        input integer from_idx;
        input integer to_idx;
        begin
            if (to_idx >= from_idx) f_dist = to_idx - from_idx;
            else                    f_dist = to_idx + N - from_idx;
        end
    endfunction

    always @(*) if (f_past_valid) begin
        assert (ptr <= LAST);
        assert ((grant & (grant - 1'b1)) == {N{1'b0}});
        assert ((grant & ~req) == {N{1'b0}});
        assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
        assert (found == (req != {N{1'b0}}));
        if (found) assert (grant[winner]);
    end

    always @(posedge clk) if (f_past_valid) begin
        if (!$past(rst_n))
            assert (ptr == ZERO);
        else if ($past(found))
            assert (ptr == (($past(winner) == LAST) ? ZERO : ($past(winner) + ONE)));
        else
            assert (ptr == $past(ptr));
    end

    genvar f_i;
    generate
        for (f_i = 0; f_i < N; f_i = f_i + 1) begin : g_formal
            // Cycles requester f_i has waited with its request held.
            reg [31:0] f_wait;
            initial f_wait = 32'd0;
            always @(posedge clk) begin
                if (!rst_n)                          f_wait <= 32'd0;
                else if (req[f_i] && !grant[f_i])    f_wait <= f_wait + 32'd1;
                else                                 f_wait <= 32'd0;
            end

            always @(*) if (f_past_valid) begin
                // Round-robin order: nobody requesting sits between ptr and the winner.
                if (found && (f_dist(ptr, f_i) < f_dist(ptr, winner)))
                    assert (!req[f_i]);
                // Starvation bound, with its induction invariant.
                assert (f_wait <= N - 1);
                assert (f_wait + f_dist(ptr, f_i) <= N - 1);
            end

            always @(*) if (f_past_valid && rst_n) cover (grant[f_i]);
        end
    endgenerate

    always @(posedge clk) if (f_past_valid && $past(rst_n) && rst_n) begin
        cover (&req);
        cover (($past(ptr) == LAST) && (ptr == ZERO));
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter (interface_spec.md section 6).
// Two arbiters run side by side: N=4 (the default) and N=5 (not a power of
// two). Each is checked every cycle against a reference pointer model that
// searches modulo N. Per-requester wait counters fail the run if a held
// request waits N cycles. Coverage counters fail the run if a required case
// is not reached. Every failed check is reported with $error. The verdict
// is printed once, just before $finish.

`timescale 1ns/1ps
`default_nettype none

`define CHECK(cond, msg) \
    begin \
        if (cond) passed = passed + 1; \
        else begin \
            failed = failed + 1; \
            $error msg; \
        end \
    end

module rr_arbiter_tb;

    localparam integer NA   = 4;  // default N, a power of two
    localparam integer NB   = 5;  // an N that is not a power of two
    localparam integer MAXN = 8;  // widest N the shared checker handles

    reg           clk = 1'b0;
    reg           rst_n;
    reg  [NA-1:0] req_a;
    reg  [NB-1:0] req_b;
    wire [NA-1:0] grant_a;
    wire [NB-1:0] grant_b;

    rr_arbiter #(.N(NA)) dut_a (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req_a),
        .grant (grant_a)
    );

    rr_arbiter #(.N(NB)) dut_b (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req_b),
        .grant (grant_b)
    );

    always #5 clk = ~clk;

    integer passed;
    integer failed;

    // Per-instance state (instance 0 is N=4, instance 1 is N=5).
    integer ref_ptr   [0:1];
    integer waitc     [0:2*MAXN-1];
    integer cov_none  [0:1];
    integer cov_alone [0:2*MAXN-1];
    integer cov_all   [0:1];
    integer cov_held  [0:1];
    integer cov_wait  [0:1];
    integer cov_rst   [0:1];
    integer cov_wrap  [0:1];

    reg [MAXN-1:0] prev_req [0:1];
    reg            prev_rst_n;
    reg [31:0]     rng;
    reg [8*64-1:0] nonce;

    // Reference winner: the first requester at or after p, modulo n; -1 if none.
    function integer ref_winner;
        input integer    n;
        input integer    p;
        input [MAXN-1:0] r;
        integer k;
        integer idx;
        begin
            ref_winner = -1;
            for (k = 0; k < n; k = k + 1) begin
                idx = (p + k) % n;
                if ((ref_winner < 0) && r[idx]) ref_winner = idx;
            end
        end
    endfunction

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    // Check one instance's grant for this cycle, then advance its model.
    task check_inst;
        input integer    inst;
        input integer    n;
        input [MAXN-1:0] r;
        input [MAXN-1:0] g;
        integer          w;
        integer          i;
        integer          q;
        integer          held_seen;
        reg [MAXN-1:0]   exp_g;
        reg [MAXN-1:0]   rp;
        reg [MAXN-1:0]   bit_i;
        reg [MAXN-1:0]   all_m;
        begin
            rp    = prev_req[inst];
            all_m = {MAXN{1'b1}} >> (MAXN - n);
            w     = ref_winner(n, ref_ptr[inst], r);
            exp_g = {MAXN{1'b0}};
            if (w >= 0) exp_g[w] = 1'b1;

            if (g === exp_g) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d at %0t: req=%b rst_n=%b ref_ptr=%0d grant=%b expected=%b",
                       n, $time, r, rst_n, ref_ptr[inst], g, exp_g);
            end

            // Coverage.
            if (rst_n) begin
                if (r == {MAXN{1'b0}}) cov_none[inst] = cov_none[inst] + 1;
                if (r == all_m)        cov_all[inst]  = cov_all[inst] + 1;
            end
            if (!rst_n && prev_rst_n && (r != {MAXN{1'b0}}))
                cov_rst[inst] = cov_rst[inst] + 1;
            held_seen = 0;
            for (i = 0; i < n; i = i + 1) begin
                bit_i    = {MAXN{1'b0}};
                bit_i[i] = 1'b1;
                if (rst_n && (r == bit_i) && (g == bit_i))
                    cov_alone[inst*MAXN + i] = cov_alone[inst*MAXN + i] + 1;
                if (rst_n && prev_rst_n && r[i] && rp[i] &&
                    ((r & ~bit_i) != (rp & ~bit_i)))
                    held_seen = 1;
            end
            if (held_seen != 0) cov_held[inst] = cov_held[inst] + 1;

            // Fairness: a held request waits at most n-1 cycles.
            for (i = 0; i < n; i = i + 1) begin
                q = inst*MAXN + i;
                if (!rst_n) begin
                    waitc[q] = 0;
                end else if (r[i] && !g[i]) begin
                    waitc[q] = waitc[q] + 1;
                    if (waitc[q] == n - 1) cov_wait[inst] = cov_wait[inst] + 1;
                    if (waitc[q] > n - 1) begin
                        failed = failed + 1;
                        $error("N=%0d at %0t: requester %0d waited %0d cycles with its request held",
                               n, $time, i, waitc[q]);
                    end
                end else begin
                    if (r[i] && g[i]) passed = passed + 1;
                    waitc[q] = 0;
                end
            end

            // Reference pointer update at this cycle's rising edge.
            if (!rst_n) begin
                ref_ptr[inst] = 0;
            end else if (w >= 0) begin
                if (w == n - 1) cov_wrap[inst] = cov_wrap[inst] + 1;
                ref_ptr[inst] = (w + 1) % n;
            end
            prev_req[inst] = r;
        end
    endtask

    // One clock cycle: drive at the falling edge, check before the rising edge.
    task cycle;
        input          rst_val;
        input [NA-1:0] ra;
        input [NB-1:0] rb;
        begin
            @(negedge clk);
            rst_n = rst_val;
            req_a = ra;
            req_b = rb;
            #1;
            check_inst(0, NA, {{(MAXN-NA){1'b0}}, req_a}, {{(MAXN-NA){1'b0}}, grant_a});
            check_inst(1, NB, {{(MAXN-NB){1'b0}}, req_b}, {{(MAXN-NB){1'b0}}, grant_b});
            prev_rst_n = rst_n;
        end
    endtask

    initial begin : main
        integer      k;
        integer      i;
        reg [NA-1:0] ra;
        reg [NB-1:0] rb;

        passed     = 0;
        failed     = 0;
        rng        = 32'h50410061;
        prev_rst_n = 1'b0;
        for (i = 0; i < 2; i = i + 1) begin
            ref_ptr[i]  = 0;
            cov_none[i] = 0;
            cov_all[i]  = 0;
            cov_held[i] = 0;
            cov_wait[i] = 0;
            cov_rst[i]  = 0;
            cov_wrap[i] = 0;
            prev_req[i] = {MAXN{1'b0}};
        end
        for (i = 0; i < 2*MAXN; i = i + 1) begin
            waitc[i]     = 0;
            cov_alone[i] = 0;
        end
        rst_n = 1'b0;
        req_a = {NA{1'b0}};
        req_b = {NB{1'b0}};

        // The first rising edge is in reset, so both pointers become 0.
        // The pointer has no value before that, so nothing is checked yet.
        @(posedge clk);

        // 1. Reset held while requests arrive: grant follows req from
        //    pointer 0, and the pointer does not move.
        cycle(1'b0, 4'b1010, 5'b10110);
        cycle(1'b0, 4'b1111, 5'b11111);
        cycle(1'b0, 4'b0110, 5'b01100);

        // 2. No requests.
        for (k = 0; k < 3; k = k + 1) cycle(1'b1, {NA{1'b0}}, {NB{1'b0}});

        // 3. Each requester alone, two cycles each.
        for (k = 0; k < NB; k = k + 1) begin
            ra = (k < NA) ? ({{(NA-1){1'b0}}, 1'b1} << k) : {NA{1'b0}};
            rb = {{(NB-1){1'b0}}, 1'b1} << k;
            cycle(1'b1, ra, rb);
            cycle(1'b1, ra, rb);
        end

        // 4. Reset, then everyone requesting: strict rotation 0..N-1. Requester
        //    N-1 waits the longest fair wait, N-1 cycles.
        cycle(1'b0, {NA{1'b0}}, {NB{1'b0}});
        for (k = 0; k < 3*NB; k = k + 1) begin
            cycle(1'b1, {NA{1'b1}}, {NB{1'b1}});
            `CHECK((grant_a == ({{(NA-1){1'b0}}, 1'b1} << (k % NA))),
                   ("N=4 all requesting: k=%0d grant=%b, rotation 0..3 broken", k, grant_a))
            `CHECK((grant_b == ({{(NB-1){1'b0}}, 1'b1} << (k % NB))),
                   ("N=5 all requesting: k=%0d grant=%b, rotation 0..4 broken", k, grant_b))
        end

        // 5. Requester 2 held while the others change.
        for (k = 0; k < 40; k = k + 1) begin
            next_rand;
            ra = rng[3:0] | 4'b0100;
            rb = rng[8:4] | 5'b00100;
            cycle(1'b1, ra, rb);
        end

        // 6. Random subsets (plain, dense, sparse). Requests drop and rise
        //    again, and reset is asserted during traffic.
        for (k = 0; k < 600; k = k + 1) begin
            next_rand;
            case (k % 3)
                0: begin
                    ra = rng[3:0];
                    rb = rng[8:4];
                end
                1: begin
                    ra = rng[3:0] | rng[12:9];
                    rb = rng[17:13] | rng[22:18];
                end
                default: begin
                    ra = rng[3:0] & rng[12:9];
                    rb = rng[17:13] & rng[22:18];
                end
            endcase
            if ((k == 200) || (k == 201) || (k == 450))
                cycle(1'b0, ra | 4'b0001, rb | 5'b00001);
            else
                cycle(1'b1, ra, rb);
        end

        // 7. Idle tail.
        for (k = 0; k < 2; k = k + 1) cycle(1'b1, {NA{1'b0}}, {NB{1'b0}});

        // Coverage goals from interface_spec.md section 6.
        `CHECK((cov_none[0] > 0), ("coverage N=4: no cycle without requests"))
        `CHECK((cov_none[1] > 0), ("coverage N=5: no cycle without requests"))
        `CHECK((cov_all[0] > 0),  ("coverage N=4: never all requesting"))
        `CHECK((cov_all[1] > 0),  ("coverage N=5: never all requesting"))
        `CHECK((cov_held[0] > 0), ("coverage N=4: no held request among changing others"))
        `CHECK((cov_held[1] > 0), ("coverage N=5: no held request among changing others"))
        `CHECK((cov_wait[0] > 0), ("coverage N=4: longest fair wait (3 cycles) not reached"))
        `CHECK((cov_wait[1] > 0), ("coverage N=5: longest fair wait (4 cycles) not reached"))
        `CHECK((cov_rst[0] > 0),  ("coverage N=4: no reset during traffic"))
        `CHECK((cov_rst[1] > 0),  ("coverage N=5: no reset during traffic"))
        `CHECK((cov_wrap[0] > 0), ("coverage N=4: pointer never wrapped from 3 to 0"))
        `CHECK((cov_wrap[1] > 0), ("coverage N=5: pointer never wrapped from 4 to 0"))
        for (i = 0; i < NA; i = i + 1)
            `CHECK((cov_alone[i] > 0), ("coverage N=4: requester %0d never alone", i))
        for (i = 0; i < NB; i = i + 1)
            `CHECK((cov_alone[MAXN + i] > 0), ("coverage N=5: requester %0d never alone", i))

        // Verdict, printed once, just before $finish.
        nonce = {{(8*64-32){1'b0}}, "none"};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {{(8*64-32){1'b0}}, "none"};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
